-- The criteria the live figures are graded by (pipeline/dam_release/config.yaml,
-- measured against the archive in pipeline/dam_release/METHODS.md). Admins own them.
insert into public.system_settings (key, value, note) values
  ('dam_grades', '{"turbine_max_cms": 160, "inflow_high_cms": 500, "rise_mcm_per_h": 4.0, "rise_window_h": 6, "stale_after_h": 12, "min_consecutive_h": 2}'::jsonb,
   'When the app shows its own quiet dam notice (watchful) and when a release reaches the admins to review and send (releasing). Code never publishes an alert itself: safety rule 2.')
  on conflict (key) do nothing;
